/**
 * Unit tests for CategoryPlot.removeRangeMarker.
 */
public class CategoryPlot_removeRangeMarker_TriageGen2Test {

    private CategoryPlot plot;
    private Marker marker;
    private Map<Integer, ArrayList> foregroundMarkersMap;
    private Map<Integer, ArrayList> backgroundMarkersMap;

    @Before
    public void setUp() throws Exception {
        plot = new CategoryPlot();
        marker = new Marker() {}; // Dummy implementation

        // Use reflection to access private fields for setup
        // Based on the method logic, the fields are foregroundRangeMarkers and backgroundRangeMarkers
        foregroundMarkersMap = new HashMap<>();
        backgroundMarkersMap = new HashMap<>();

        Field fgField = CategoryPlot.class.getDeclaredField("foregroundRangeMarkers");
        fgField.setAccessible(true);
        fgField.set(plot, foregroundMarkersMap);

        Field bgField = CategoryPlot.class.getDeclaredField("backgroundRangeMarkers");
        bgField.setAccessible(true);
        bgField.set(plot, backgroundMarkersMap);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRemoveRangeMarker_NullMarker_ThrowsException() {
        plot.removeRangeMarker(0, null, Layer.FOREGROUND, true);
    }

    @Test
    public void testRemoveRangeMarker_Foreground_Success() {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(marker);
        foregroundMarkersMap.put(index, markers);

        boolean result = plot.removeRangeMarker(index, marker, Layer.FOREGROUND, true);

        assertTrue("Marker should have been removed", result);
        assertFalse("Marker list should be empty", markers.contains(marker));
    }

    @Test
    public void testRemoveRangeMarker_Background_Success() {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(marker);
        backgroundMarkersMap.put(index, markers);

        boolean result = plot.removeRangeMarker(index, marker, Layer.BACKGROUND, true);

        assertTrue("Marker should have been removed", result);
        assertFalse("Marker list should be empty", markers.contains(marker));
    }

    @Test
    public void testRemoveRangeMarker_MarkerNotFound_ReturnsFalse() {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(new Marker() {}); // Different marker
        foregroundMarkersMap.put(index, markers);

        boolean result = plot.removeRangeMarker(index, marker, Layer.FOREGROUND, true);

        assertFalse("Should return false when marker is not in list", result);
    }

    @Test
    public void testRemoveRangeMarker_NotifyFalse_NoException() {
        // Testing the 'notify' branch: when removed is true but notify is false
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(marker);
        foregroundMarkersMap.put(index, markers);

        // We can't easily verify fireChangeEvent() without a spy, 
        // but we ensure the method completes without error.
        boolean result = plot.removeRangeMarker(index, marker, Layer.FOREGROUND, false);

        assertTrue(result);
        assertFalse(markers.contains(marker));
    }

    @Test(expected = NullPointerException.class)
    public void testRemoveRangeMarker_IndexDoesNotExist_ThrowsException() {
        // If the index is not in the map, markers.remove() will throw NPE because markers is null
        plot.removeRangeMarker(99, marker, Layer.FOREGROUND, true);
    }
}
